import { NotFoundError } from '../errors/DomainError';
import { OrderLine } from '../order/OrderLine';
import { Product } from '../product/Product';
import { ProductRepository } from '../product/ProductRepository';

/**
 * Reserves and releases stock for a set of order lines.
 * Reservation is all-or-nothing: every line is checked before any stock is touched.
 */
export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  reserve(lines: readonly OrderLine[]): void {
    const consolidated = OrderLine.consolidate(lines);
    const allocations = consolidated.map((line) => ({ line, product: this.require(line.productId) }));

    for (const { line, product } of allocations) {
      product.assertCanReserve(line.quantity);
    }
    for (const { line, product } of allocations) {
      product.reserve(line.quantity);
      this.products.save(product);
    }
  }

  release(lines: readonly OrderLine[]): void {
    for (const line of lines) {
      const product = this.require(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    }
  }

  private require(productId: string): Product {
    const product = this.products.findById(productId);
    if (!product) {
      throw new NotFoundError('Product', productId);
    }
    return product;
  }
}

